  namedColours: number;
  /** What one full roll or carton costs at the base rate, ex GST. */
  costPerBulkUnit: number;
  /** How much dearer a cut is, as a %. 17.5% on commercial sheet by construction. */
  cutPremiumPct: number | null;
  /** How much cheaper the over-300 rate is, as a %. */
